export default {
	getAllStudiensemesterAndAktOrNext() {
		return {
			method: 'get',
			url: '/api/frontend/v1/organisation/Studiensemester/getAllStudiensemesterAndAktOrNext',
		};
	},
	getAll(order = null, start = null)
	{
		return {
			method: 'get',
			url: 'api/frontend/v1/organisation/studiensemester/getAll',
			params: { order, start }
		};
	},
	getStudiensemester() {
		return {
			method: 'get',
			url: '/api/frontend/v1/Studiensemester/getStudiensemester'
		};
	},
	current() {
		return {
			method: 'get',
			url: 'api/frontend/v1/organisation/studiensemester/current'
		};
	},
	set(studiensemester_kurzbz) {
		return {
			method: 'post',
			url: 'api/frontend/v1/organisation/studiensemester/set',
			params: {
				studiensemester_kurzbz
			}
		};
	},
	getContainingOrNearestByDateRange(from, to) {
		return {
			method: 'get',
			url: 'api/frontend/v1/organisation/studiensemester/getContainingOrNearestByDateRange',
			params: {
				from,
				to,
			}
		};
	},
};
